<?php
declare(strict_types=1);
namespace Ulgg\Checkpoint2026;

use InvalidArgumentException;
use DateTimeImmutable;
use DateTimeZone;

/**
 * M3-B signed synthetic source evidence, scoped to verified server-side identity.
 * This verifies an HMAC generated by a trusted offline fixture issuer; never
 * accepts an HTTP-provided "verified=true" bit. No production key is present.
 */
final class SourceProvenance
{
    public const SCHEMA_FINGERPRINT='8de93e52c187059f924be7ffa9c6755767f3fe4bc2d104cc097098de6bd7cd34';

    private const FIELDS=[
        'contract','dataset','mode','issuer','period_start','as_of','timezone',
        'schema_fingerprint','source_watermark','source_revision',
        'source_complete','source_rows','expected_rows','missing_slices',
        'fact_sha256','scope_hash',
    ];

    public static function canonical(array $source): string
    {
        $value=self::sorted($source);
        return json_encode($value,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
    }

    private static function sorted(mixed $value): mixed
    {
        if(!is_array($value))return $value;
        // PHP 8.0 compatibility: array_is_list() was introduced in 8.1.
        $position=0;
        $isList=true;
        foreach(array_keys($value) as $key){
            if($key!==$position++){ $isList=false; break; }
        }
        if($isList){
            return array_map([self::class,'sorted'],$value);
        }
        ksort($value,SORT_STRING);
        foreach($value as &$item){$item=self::sorted($item);}
        unset($item);
        return $value;
    }

    private static function validTaipeiTime(mixed $candidate):bool
    {
        if(!is_string($candidate)
            || preg_match('/^\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2}$/D',$candidate)!==1){
            return false;
        }
        $date=DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',
            $candidate,new DateTimeZone('Asia/Taipei'));
        return $date!==false && $date->format('Y-m-d H:i:s')===$candidate;
    }

    public static function scopeHash(string $scope,string $secret):string
    {
        self::requireKey($secret);
        if($scope==='' || strlen($scope)>256)throw new InvalidArgumentException('BAD_TRUSTED_SCOPE');
        return hash_hmac('sha256',"ulgg-checkpoint26-scope\0".$scope,$secret);
    }

    public static function hashFacts(array $rows):string
    {
        $copy=array_values($rows);
        usort($copy,static function($a,$b):int{
            $idA=(int)($a['match_id']??0);
            $idB=(int)($b['match_id']??0);
            return ($idA<=>$idB)
                ?: strcmp((string)($a['side']??''),(string)($b['side']??''))
                ?: strcmp(self::canonical((array)$a),self::canonical((array)$b));
        });
        return hash('sha256',self::canonical($copy));
    }

    private static function requireKey(string $key):void
    {
        if(strlen($key)<32)throw new InvalidArgumentException('TRUSTED_KEY_REQUIRED');
    }

    /** Only used with an injected test key in offline fixture tests. */
    public static function signForSyntheticFixture(array $claims,string $key):string
    {
        self::requireKey($key);
        return hash_hmac('sha256',"checkpoint2026:m3b:provenance:v1\n".self::canonical($claims),$key);
    }

    public static function verify(array $attestation,string $trustedKey,string $trustedScope,string $asOf,array $rows,string $expectedDataset='PVP_MATCH_FACT'):array
    {
        self::requireKey($trustedKey);
        $denied=['status'=>'UNKNOWN','source_verified'=>false,'mode'=>'UNVERIFIED',
            'source_watermark'=>null,'schema_fingerprint'=>null,
            'provenance_sha256'=>null,'reason'=>'UNTRUSTED_EVIDENCE'];
        $claims=$attestation['claims']??null;
        $signature=$attestation['signature']??null;
        if(!is_array($claims)||!is_string($signature)
            || preg_match('/^[0-9a-f]{64}$/D',$signature)!==1){
            return $denied;
        }
        $keys=array_keys($claims);sort($keys,SORT_STRING);
        $expected=self::FIELDS;sort($expected,SORT_STRING);
        if($keys!==$expected){
            $denied['reason']='UNEXPECTED_EVIDENCE_FIELDS';return $denied;
        }
        $signed=self::signForSyntheticFixture($claims,$trustedKey);
        if(!hash_equals($signed,$signature)){
            $denied['reason']='INVALID_SIGNATURE';return $denied;
        }
        if(($claims['contract']??null)!=='checkpoint2026/provenance-v1'
            || ($claims['mode']??null)!=='SYNTHETIC_STAGING'
            || ($claims['issuer']??null)!=='M3B_ISOLATED_TEST_ISSUER'){
            $denied['reason']='UNAPPROVED_ISSUER';return $denied;
        }
        if(($claims['dataset']??null)!==$expectedDataset
            || !in_array($expectedDataset,['PVP_MATCH_FACT','CUP_PUBLIC','ANNUAL_PVP_CUP'],true)){
            $denied['reason']='SOURCE_DATASET_MISMATCH';return $denied;
        }
        if(!self::validTaipeiTime($asOf)
            || !self::validTaipeiTime($claims['source_watermark']??null)
            || ($claims['as_of']??null)!==$asOf
            || ($claims['period_start']??null)!=='2026-01-01 00:00:00'
            || $asOf<'2026-01-01 00:00:00' || $asOf>='2027-01-01 00:00:00'
            || ($claims['timezone']??null)!=='Asia/Taipei'){
            $denied['reason']='TIME_SCOPE_MISMATCH';return $denied;
        }
        if(!hash_equals(self::SCHEMA_FINGERPRINT,(string)($claims['schema_fingerprint']??''))){
            $denied['reason']='SCHEMA_MISMATCH';return $denied;
        }
        if(!hash_equals(self::scopeHash($trustedScope,$trustedKey),(string)($claims['scope_hash']??''))){
            $denied['reason']='SUBJECT_SCOPE_MISMATCH';return $denied;
        }
        if(!is_string($claims['source_revision'])
            || $claims['source_revision']===''
            || !is_string($claims['source_watermark'])
            || $claims['source_watermark']<$asOf
            || $claims['source_complete']!==true
            || !is_int($claims['source_rows']) || $claims['source_rows']<0
            || !is_int($claims['expected_rows']) || $claims['expected_rows']<0
            || $claims['source_rows']!==$claims['expected_rows']
            || $claims['source_rows']!==count($rows)
            || !is_int($claims['missing_slices']) || $claims['missing_slices']!==0){
            $denied['reason']='INCOMPLETE_OR_STALE_SOURCE';return $denied;
        }
        if(!is_string($claims['fact_sha256'])
            || !hash_equals(self::hashFacts($rows),$claims['fact_sha256'])){
            $denied['reason']='FACT_HASH_MISMATCH';return $denied;
        }
        return [
            'status'=>'VERIFIED','source_verified'=>true,'mode'=>'SYNTHETIC_STAGING',
            'source_watermark'=>$claims['source_watermark'],
            'schema_fingerprint'=>self::SCHEMA_FINGERPRINT,
            'provenance_sha256'=>hash('sha256',self::canonical($claims)),
            'reason'=>null,
        ];
    }
}
